import{_ as e,H as s,f as t,i}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"14 | 数据清洗：挑战大量噪音的需求","description":"","frontmatter":{},"headers":[{"level":2,"title":"人人都能用的“AI 清洗法”","slug":"人人都能用的-ai-清洗法","link":"#人人都能用的-ai-清洗法","children":[{"level":3,"title":"✦ 获取数据：设计自己的接口","slug":"✦-获取数据-设计自己的接口","link":"#✦-获取数据-设计自己的接口","children":[]},{"level":3,"title":"✦ 清洗数据：智取，不硬刚","slug":"✦-清洗数据-智取-不硬刚","link":"#✦-清洗数据-智取-不硬刚","children":[]},{"level":3,"title":"✦ 手动测试","slug":"✦-手动测试","link":"#✦-手动测试","children":[]},{"level":3,"title":"✦ 设计 prompt","slug":"✦-设计-prompt","link":"#✦-设计-prompt","children":[]}]},{"level":2,"title":"躺着收图","slug":"躺着收图","link":"#躺着收图","children":[{"level":3,"title":"✦ 跑机任务 1：兼容 ChatGPT","slug":"✦-跑机任务-1-兼容-chatgpt","link":"#✦-跑机任务-1-兼容-chatgpt","children":[]},{"level":3,"title":"✦ 跑机任务 2：联网，效率起飞","slug":"✦-跑机任务-2-联网-效率起飞","link":"#✦-跑机任务-2-联网-效率起飞","children":[]},{"level":3,"title":"✦ 拓展玩法","slug":"✦-拓展玩法","link":"#✦-拓展玩法","children":[]}]},{"level":2,"title":"小黑板","slug":"小黑板","link":"#小黑板","children":[]},{"level":2,"title":"踏浪扬帆","slug":"踏浪扬帆","link":"#踏浪扬帆","children":[]}],"relativePath":"零基础GPT应用入门课/14｜数据清洗：挑战大量噪音的需求.md","filePath":"零基础GPT应用入门课/14｜数据清洗：挑战大量噪音的需求.md","lastUpdated":1795561467000}'),n={name:"零基础GPT应用入门课/14｜数据清洗：挑战大量噪音的需求.md"};function p(l,a,o,h,c,r){return s(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="_14-数据清洗-挑战大量噪音的需求" tabindex="-1">14 | 数据清洗：挑战大量噪音的需求 <a class="header-anchor" href="#_14-数据清洗-挑战大量噪音的需求" aria-label="Permalink to &quot;14 | 数据清洗：挑战大量噪音的需求&quot;">​</a></h1><p>你好，我是键盘，我们继续驯服 GPT。</p><p>数据的处理通常有两种类型，一种是上节课的“重建秩序”，所有的数据都是有用的，而且让你在有序的状态下可以轻松地填充更多内容。另一种，就是这节课我们要讲的典型情况“沙里淘金”。什么意思呢？就是说交给 GPT 处理的数据里，只有一部分是有用的，其他的全是干扰。我们把这种数据叫做脏数据（Dirty Read），里面的干扰项和多余的信息，就是噪音。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/14/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/14/1.png" alt=""></a></p><p>我会结合一个可调整多个参数的智能配图方案来讲解实现过程，搞定它，你的所有配图需求就不用再通过人力搜索了。另外，区别于之前分享过的 Unsplash 接口，这个新接口获取到的可商用资源，格局又打开了“亿”点，除了照片题材，它还支持插画、矢量图、视频等等。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#温习 Unsplash 接口：</span></span>\n<span class="line"><span>![](https://source.unsplash.com/1600x900/?&lt;关键词&gt;)</span></span></code></pre></div><h2 id="人人都能用的-ai-清洗法" tabindex="-1">人人都能用的“AI 清洗法” <a class="header-anchor" href="#人人都能用的-ai-清洗法" aria-label="Permalink to &quot;人人都能用的“AI 清洗法”&quot;">​</a></h2><p>我们的整活目标是让包含众多图片链接的数据流到自己手里，从中自动洗出想要的图片。这个思路同样适用于其他具备物料需求的场景，比如获取某段时间的一类数据、文章配图、宣传材料的视频和 BGM 等等。</p><p>实现原理比较简单，而且通用。以“清洗图片”为例，我简单描述下。</p><ol><li><p>我们自己手动获取某个可商用图片网站的 API key（以下用“私钥”指代）。结合我们想要的目标图片细节要求，让 GPT 将私钥和参数组装成“请求链接”。</p></li><li><p>在浏览器中输入请求链接，如果你有 ChatGPT Plus，也可以用联网插件直接处理，得到一个用来初筛目标范围的 JSON 文件。</p></li><li><p>让 GPT 从 JSON 文件中提取出合适的图片链接。</p></li><li><p>让 GPT 将其输出为图片或其他资源。</p></li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/14/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/14/2.png" alt=""></a></p><ul><li>实现流程（API 即接口，key 即私钥，最后将链接解析为图片的处理一般叫“渲染”）</li></ul><p>这节课的案例，我选取了比较贴合需求的图片网站 Pixabay 来做方案的接口。没有技术背景的朋友可以将“接口”简单理解为标准化管道，用管道来连接不同的服务，数据就能流通起来。</p><p>正式开始之前，再提示你一下准备工作。</p><ol><li>注册一个 Pixabay 账户：用来获取 API key，使用它来组成“请求链接”，获取目标JSON 文件。</li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/14/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/14/3.png" alt=""></a></p><ul><li>绿框内就是私钥，复制下来备用</li></ul><ol start="2"><li>推荐使用 GPT-4 和 WebPilot 插件：因为 GPT 模型无法直接联网，需要搭配联网插件来处理接口。假如你是 ChatGPT Plus 会员，使用这个组合的效果最好。</li></ol><p>假如你的手里只有 ChatGPT，也可以兼容。只要通过一些参数处理手段，比如开启“编辑精选”精细筛选题材或尺寸等等，让目标 JSON 大幅缩短而且变得规整好读，然后手动发给ChatGPT 来提取，让 ChatGPT 写一个本地的批处理提取脚本，也是没问题的。</p><p>准备完毕，我们要开始整活了。</p><h3 id="✦-获取数据-设计自己的接口" tabindex="-1">✦ 获取数据：设计自己的接口 <a class="header-anchor" href="#✦-获取数据-设计自己的接口" aria-label="Permalink to &quot;✦ 获取数据：设计自己的接口&quot;">​</a></h3><p>刚刚我们说了用 Pixabay 的接口来获取图片。具体怎么做呢？先看看官方接口文档，了解这个接口都能干什么。假如你对英语阅读有一定的困难，使用智学三件套中分享的沉浸式翻译来做辅助即可。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Pixabay 给出的参数（Parameters）总共有 17 个， 参数=什么 这个结构的作用就是告诉接口</span></span></code></pre></div><p>“你要什么细节”，参数里面主要包含两类。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>字符串 str= ，比如 q=read 表示“搜索关键词 read 相关的图片”。</span></span>\n<span class="line"><span>开关 bool=true/false ，比如 editors_choice=true 表示“打开编辑精选”。（=true 就是</span></span></code></pre></div><ul><li>开启的意思，后面同理）</li></ul><p>我从 17 个参数里挑出了重点影响结果质量和处理效率的部分，下面的图稿里也提供了注解，供你参考。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/14/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/14/4.png" alt=""></a></p><ul><li>Pixabay Images API</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>参数的使用也非常简单，在 http://pixabay.com/api/  后面加上参数是什么，还有状态</span></span></code></pre></div><p>开（ture）或关（false）就可以了，没有编程什么事。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>之后你会得到下面这个基础的请求链接 。使用时记得替换 你的私钥 和目标关键词 keywords</span></span></code></pre></div><p>，这样它才是完整的。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://pixabay.com/api/?key=`你的私钥`&amp;q=`keywords`&amp;image_type=`type`</span></span></code></pre></div><p>然后把完整的请求链接贴到浏览器地址栏中，现在我们要来面对脏兮兮的 JSON 文件了。这里可以先打住，思考一下，如果这个 JSON 可以变简单，处理不就更轻松了？ChatGPT 无法接收冗长信息的问题也将迎刃而解。</p><h3 id="✦-清洗数据-智取-不硬刚" tabindex="-1">✦ 清洗数据：智取，不硬刚 <a class="header-anchor" href="#✦-清洗数据-智取-不硬刚" aria-label="Permalink to &quot;✦ 清洗数据：智取，不硬刚&quot;">​</a></h3><p>想要让“清洗”变简单，就一定要掌握 2 个重点参数。</p><ol><li>编辑精选。是的，让赛博编辑为你打工，自动挑出质量更好的结果。对应代码中的</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>editors_choice=true。</span></span>\n<span class="line"><span>干得“漂亮”，pretty=true。让输出的 JSON 文件变整洁，既方便 GPT 更快地计算，还</span></span></code></pre></div><ul><li>能大幅节省 Token 的用量，当你使用 GPT API 来做方案的时候，节省 Token 就等于省钱。所以，务必带上。</li></ul><p>组合起来，就能得到一个用于获取目标 JSON 的“漂亮请求”。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://pixabay.com/api/?key=`填入你的key`&amp;q=`keywords`&amp;image_type=`type`&amp;editors_</span></span></code></pre></div><h3 id="✦-手动测试" tabindex="-1">✦ 手动测试 <a class="header-anchor" href="#✦-手动测试" aria-label="Permalink to &quot;✦ 手动测试&quot;">​</a></h3><p>接下来不要急匆匆开始写 prompt，玩转 GPT 的正确姿势永远是一步一步思考。我们先在浏览器中粘贴上面的“漂亮请求”，观察能不能手动“洗”出图片。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/14/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/14/5.png" alt=""></a></p><ul><li>手动洗图（可行但低效）</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>图稿的左侧是没有开启 pretty 的后果，肉眼可见的“脏”。在 GPT 中流转这样的材料真的脑</span></span>\n<span class="line"><span>壳疼，你疼，AI 也疼。中间开启 pretty 后瞬间“漂亮”，官方命名诚不我欺。这里面可以清晰</span></span>\n<span class="line"><span>地找到一个标签为 largeImageURL 的链接。全场最靓的高清大图，就是你了！我们粘贴链</span></span></code></pre></div><p>接打开，成功。</p><p>通过这个验证，我们就可以设计一行告诉 GPT 提取配图，渲染到对话框的 Markdown 模版。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>![配图](the first &quot;largeImageURL&quot; in JSON)</span></span></code></pre></div><p>上面所有设计好的参数和私钥也准备交给 GPT，让它来智能组装。</p><h3 id="✦-设计-prompt" tabindex="-1">✦ 设计 prompt <a class="header-anchor" href="#✦-设计-prompt" aria-label="Permalink to &quot;✦ 设计 prompt&quot;">​</a></h3><p>只要掌握了接口的设计逻辑，所有具备智能搭配属性的需求都能用，prompt 同理。我会聚焦最核心的提取部分，你按需延展即可。这种执行目标直接了当的情况，我定义为“直接提问型”，不需要什么角色扮演，直说需求就好。</p><ul><li>直接提问型 prompt 框架</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请&lt;做什么&gt;:</span></span></code></pre></div><ul><li>步骤：模版：说明：</li></ul><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">请一步一步思考 #标配</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">指令</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>这个 prompt 需要解决 5 个核心问题。</p><ol><li>提供私钥，让 GPT 自动拼合出获取 JSON 的“漂亮请求”，然后通过联网插件来处理这个请求。这里需要清理一个广泛的误区，不是说更高级的 GPT-4 就能联网，去处理网络请求，像 Bard 这种联网模型才能够直接处理网络请求。要记得，联网插件才是连接的核心。</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>`API`:  填写你的key，注意数据安全，私钥不可公布和分享。</span></span>\n<span class="line"><span>获取图片时你可能需要多个关键词，API 的 q 参数里用 关键词 + 关键词 这样的格式来支</span></span></code></pre></div><ul><li>持。用单样本示例（One-Shot Prompt）来教给 GPT 即可。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>多个关键词的情况，使用形式：keyword A+keyword B+…+keyword N</span></span></code></pre></div><ol start="3"><li>指明目标题材。你想要照片、插画还是矢量图？用综合人设用的方法，多设计一个开关来切换就可以。</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>`type`: all(Default),  photo, illustration, vector</span></span></code></pre></div><ol start="4"><li>告诉 GPT 怎么提取目标图片。使用前面提到的 Markdown 配图代码就可以，这里我还要求默认给目标图片配上和关键词相关的一句名人名言。</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>![配图](the first &quot;largeImageURL&quot; in JSON)</span></span>\n<span class="line"><span>输出关键词相关的名人警句，使用Markdown引用格式渲染。不超过40个字。</span></span></code></pre></div><ol start="5"><li>使用“判断技巧”，假如用户没有插件的“通行证”，那么只输出“漂亮请求”代码，用户通过请求拿到的数据发给 GPT 也能实现。</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>插件判断—&gt;N：只执行到步骤2，等待用户输入JSON或者目标链接，再继续。Y：执行全流程。</span></span>\n<span class="line"><span>#由于GPT自己无法判断插件情况，设计一个对应的开关指令来应对：</span></span>\n<span class="line"><span>/plugin：Y=开启插件（默认），N=无插件</span></span></code></pre></div><p>整合起来，你会得到一个 pretty prompt。如果你不想频繁地修改 prompt，记住一个永不过时的指导原则：更多思考，更少设计。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/14/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/14/6.png" alt=""></a></p><ul><li><p>洗图 prompt（注意替换私钥和 keywords）</p></li><li><p>请根据我输入的关键词来配图：</p></li><li><p>步骤：</p></li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1、将关键词翻译为英语`keywords`（此处不使用插件）。多个关键词的情况，使用形式：keyword A+keyw</span></span>\n<span class="line"><span>2、拼合成API链接，用代码块输出：</span></span>\n<span class="line"><span>https://pixabay.com/api/?key=`API`&amp;q=`keywords`&amp;image_type=`type`&amp;editors_choice=</span></span>\n<span class="line"><span>3、插件判断—&gt;N：只执行到步骤2，等待用户输入JSON或者目标链接，再继续。Y：执行全流程。</span></span>\n<span class="line"><span>4、将接口返回的JSON中的目标图片提取出来，用Markdown渲染，不要用代码块回复。</span></span>\n<span class="line"><span>5、输出模版：</span></span>\n<span class="line"><span>## 关键词</span></span>\n<span class="line"><span>![配图](the first &quot;largeImageURL&quot; in JSON)</span></span>\n<span class="line"><span>输出关键词相关的名人名言，使用Markdown引用格式渲染。不超过40个字。示例：</span></span>\n<span class="line"><span>&gt; “伸手摘星，即便一无所获，也不至于满手污泥”—李奥贝纳（Leo Burnett）</span></span></code></pre></div><ul><li>说明：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>`API`:  替换你的key</span></span>\n<span class="line"><span>`type`: all(Default),  photo, illustration, vector</span></span>\n<span class="line"><span>/plugin：Y=开启插件（默认），N=无插件</span></span>\n<span class="line"><span>—</span></span></code></pre></div><ul><li>请一步一步思考。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/plugin= N，`关键词`=阅读</span></span></code></pre></div><p>这里面有 2 个实用小技巧。</p><ol><li>步骤 1 的翻译提醒“此处不使用插件”，用来告诉模型“好钢用在刀刃上”，不是所有步骤都需要联网处理。</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>尽可能利用 AI 的优势，我用 Markdown 引用格式示例后面加 &gt; 搭配名人名言 的方式，让</span></span></code></pre></div><ul><li>GPT 自动去填充信息，这样结果就不是单调的图片，而是可以灵活组装的材料。</li></ul><h2 id="躺着收图" tabindex="-1">躺着收图 <a class="header-anchor" href="#躺着收图" aria-label="Permalink to &quot;躺着收图&quot;">​</a></h2><p>现在我们只要提出关键词需求就可以自动获取目标图片了，来看看实际跑机怎么做。</p><h3 id="✦-跑机任务-1-兼容-chatgpt" tabindex="-1">✦ 跑机任务 1：兼容 ChatGPT <a class="header-anchor" href="#✦-跑机任务-1-兼容-chatgpt" aria-label="Permalink to &quot;✦ 跑机任务 1：兼容 ChatGPT&quot;">​</a></h3><p>先来解决比较艰苦的“村里没联网”的情况，对应的“洗图 prompt”结尾的指令是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/plugin= N，`关键词`=阅读</span></span></code></pre></div><ul><li>🤖️ ChatGPT</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/14/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/14/7.png" alt=""></a></p><ul><li>ChatGPT 清洗关于阅读的图片</li></ul><p>判断成功执行，复制“API 链接”到浏览器地址栏，可以看到 JSON 数据。</p><ul><li>第一种情况：贴入单个目标</li></ul><p>由于我们开启了编辑精选和 pretty 参数，初筛结果干净多了，打开就能靠肉眼快速定位到“阅读”的目标大图链接，将它交给 ChatGPT 直接渲染出来，搞定。</p><ul><li>第二种情况：贴入 JSON，智取多个结果</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我们试试组合 关键词 A + 关键词 B ，上面的截图里我的关键词是“阅读 + 光线”，结果精准</span></span></code></pre></div><p>匹配，没有问题。</p><p>再试一下 JSON 片段的提取方式。注意，ChatGPT 的字数局限依然存在，超过 1200 汉字的片段，要么分拆输入，要么采用接下来我分享的技巧：截取一个字数不超标的片段就好，不用精确计算，大概 1000 字的长度就不会有太多段落。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>根据观察，目标 JSON 文件里面有两个 _640.jpg 结尾的链接，对应 2 张中等精度的图片，</span></span></code></pre></div><p>我们让 ChatGPT 根据这个线索自动从贴入的 JSON 片段中提取出来，同样顺利搞定。</p><p>假如你的配图场景是手机壁纸，或者其他不讲究图片方向的情况，以上输出就可以满足你的需求。但是在日常工作和写文章的情景中，我们使用更多的是横版图片，根据官方文档提供的参</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>数，在“漂亮请求”中加入 &amp;orientation=horizon （表示构图方向为水平）就可以解决，</span></span></code></pre></div><p>当然你也可以在迭代沟通中补充参数的改动需求。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>最后再试试切换题材？改变 type 参数，让它变成插画（illustration），稳！</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/14/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/14/8.png" alt=""></a></p><ul><li>17 个参数，成百上千的可能</li></ul><h3 id="✦-跑机任务-2-联网-效率起飞" tabindex="-1">✦ 跑机任务 2：联网，效率起飞 <a class="header-anchor" href="#✦-跑机任务-2-联网-效率起飞" aria-label="Permalink to &quot;✦ 跑机任务 2：联网，效率起飞&quot;">​</a></h3><p>现在我们证实了“孤岛模型”都能轻松解决任务，GPT-4 “接上网线”不就跟喝水一样简单了？试试就知道。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>拿掉指令中的 /plugin= N ，在 prompt 说明中等效于 /plugin= Y ，也就是默认视为用户</span></span></code></pre></div><p>开启了插件。使用关键词“水母”来验收。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/14/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/14/9.png" alt=""></a></p><ul><li>GPT-4 x WebPilot 自动洗图（水母）</li></ul><p>全流程提取自动化完美解决，脏活累活都让 GPT-4 包了。展开 WebPilot 的执行细节，你看这滚动条占比就能感受到 AI 都承受了什么。不过这都和我们没关系了，后续输入关键词，躺着拿图就行了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/14/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/14/10.png" alt=""></a></p><ul><li>最后还是 GPT-4 默默扛下了所有</li></ul><p>好了，关闭箭头，让我们从此告别让人“眼前一黑”的数据清洗工作。</p><h3 id="✦-拓展玩法" tabindex="-1">✦ 拓展玩法 <a class="header-anchor" href="#✦-拓展玩法" aria-label="Permalink to &quot;✦ 拓展玩法&quot;">​</a></h3><p>假如你有一系列的关键词，还可以让 GPT 整理成一份完整的 JSON 文件，或者干脆就用一个符号，比如“，”做隔断，接着贴给 GPT，设计暗号 “1” 来触发分段提取。这样的好处是省去了后续的重复输入。只要第一次调通了，一次性生成几个月的配图材料绝对轻而易举。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>假如你想配可商用的视频呢？安排！这里选取关键词 light 来做验收。</span></span>\n<span class="line"><span>同样从官方 API 文档中可以得到视频的请求链接，多加一节 video/，其他的可以原封不动。</span></span>\n<span class="line"><span>https://pixabay.com/api/videos/</span></span>\n<span class="line"><span>?key=`key`&amp;q=`keywords`&amp;video_type=`type`&amp;editors_choice=true&amp;pretty=true</span></span>\n<span class="line"><span>其中，视频的 type 支持默认的 “all”，另外还有影视 “film”，动画 “animation”，按需定义就</span></span></code></pre></div><p>好。</p><ul><li>🤖️ ChatGPT</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/14/11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/14/11.png" alt=""></a></p><p>输出的素材传送门：在创造的过程中，神说：“要有光”，就有了光。</p><p>以前，即使已经掌握了一个可商用的素材平台，普通人获取这些素材的方式都离不开重复且线性的人力劳作，而现在 AI 就是要用来干掉这些毫无意义的工作，让我们腾出精力去应对高价值的事项。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/14/12.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/14/12.png" alt=""></a></p><ul><li>毫无意义的重复劳作</li></ul><p>最后我想和你分享的是，JSON 可以提取的资源远远不止链接，只要是清洗数据，都可以用这节课的方法，比如下面的法律文书清洗。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/14/13.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/14/13.png" alt=""></a></p><ul><li>清洗法律文书</li></ul><p>这是我在 3 月份做的一个真实需求。我将爬取的法律文书数据交给 GPT，从一大段凌乱的JSON 中提取出一个规整的信息表格，对其进行总结，提炼出规律和思考。彼时我刚入门，还没有学习 prompt 工程，但是 ChatGPT 和 GPT-4 都跑通了，也就成为本次分享的星火，保留至今。</p><h2 id="小黑板" tabindex="-1">小黑板 <a class="header-anchor" href="#小黑板" aria-label="Permalink to &quot;小黑板&quot;">​</a></h2><p>现在我们已经讲齐了日常数据整理的两种情况，重建秩序和沙里淘金。这节课主要分享的是后者，通过寻找一个合适的接口获取包含大量数据的 JSON 文件，再通过 GPT 自动提取的方式，将目标物料“清洗”出来。掌握了这样的方法，清洗其他类型的数据也就有套路可循了。</p><p>设计 GPT 解决方案的过程，我建议向上兼容和向下兼容都要考虑，真正实现人人能用。普通用户靠 ChatGPT 能解决问题，高级用户使用联网插件让实现更高效。</p><p>接口其实离我们并不远，OpenAI 也提供了 API keys，无论是接入 GPT 来打造自己的 AI，还是体验各种第三方服务，比如备受赞誉的 OpenAI Translator，我们都需要这把私钥。以前还需要研发同学帮忙才能通过网络爬虫的方式获取到宝贵的数据，如今，人人都可以用 AI 来取代低价值的重复工作，做更有价值的事情，做更好的决策。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/14/14.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/14/14.png" alt=""></a></p><ul><li>OpenAI 的 API keys</li></ul><p>最后我们总结一下，通过设计一个可调整多个参数的智能配图方案，我们都掌握了哪些方法呢？</p><ol><li><p>设计之前，一定要阅读官方接口文档，少走弯路。</p></li><li><p>智取结果，用参数来初筛 JSON，使计算和提取变简单。</p></li><li><p>量身定制参数，获得千变万化的智能结果。</p></li><li><p>先手动验证再攻破自动方案，稳扎稳打。</p></li><li><p>更多思考，更少设计，减少来回折腾。</p></li><li><p>让 GPT 自动拼合链接。</p></li><li><p>设计一个插件状态开关，指导 GPT 区分处理。既能向上支持联网，也能向下兼容孤岛模型。</p></li><li><p>好钢用在刀刃上，不是所有步骤都需要插件。</p></li><li><p>设计方案时，想方设法利用 AI 的优势，打造灵活、高效的组合。</p></li></ol><p>通过亲自实践来吃透方法，我们就可以告别让人“眼前一黑”的数据清洗工作，躺收结果。但其实，哪有什么岁月静好，不过是通过思考，把负重前行转移给 AI 罢了。</p><p>要点：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/14/15.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/14/15.png" alt=""></a></p><h2 id="踏浪扬帆" tabindex="-1">踏浪扬帆 <a class="header-anchor" href="#踏浪扬帆" aria-label="Permalink to &quot;踏浪扬帆&quot;">​</a></h2><p>小伙伴们自己的清洗需求肯定不少，有些只是没有找到合适的 AI 切入点。关于清洗其他类型的数据你有什么想法吗？尽量试试套用这节课的方法而不是照搬 prompt 模版，设计一套自己的自动化清洗方案。</p><p>期待在评论区看到你的思考或感受分享，也欢迎你将这节课分享给感兴趣的朋友们，戳此加入课程交流群，我们下节课再会。</p>',141)])])}const d=e(n,[["render",p]]);export{u as __pageData,d as default};
